(function() {
  try {
    const theme = localStorage.getItem('nour-theme');
    const html = document.documentElement;
    if (theme === 'light') {
      html.classList.remove('dark');
      html.style.colorScheme = 'light';
    } else {
      html.classList.add('dark');
      html.style.colorScheme = 'dark';
    }
  } catch (e) {}
})();
